INSERT INTO public.event (id, organizer_id, org_name, category, title, body, campus, venue, starts_at, ends_at, capacity, team_size, signup_count, status, created_at, updated_at, deleted_at) VALUES ('2367be81-deb9-40b8-b5e2-c8981b9510ae', '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', 'ZJU Football Association', 'sports', 'Inter-college 5-a-side tournament', 'Teams of five plus one substitute. Group stage in the morning, knockouts after lunch.
INSERT INTO public.event (id, organizer_id, org_name, category, title, body, campus, venue, starts_at, ends_at, capacity, team_size, signup_count, status, created_at, updated_at, deleted_at) VALUES ('92db41c8-fb8a-4af3-b4f2-6942e24b92a2', 'c43d6df5-b777-49d0-9622-d609aec7caee', 'Student Societies Council', 'club', 'Autumn club fair — 40 societies, one afternoon', 'Every society with a stall: sports, music, debate, photography, volunteering, tech. Most will sign you up on the spot.', 'zijingang', 'Main square, Zijingang', '2026-10-28 13:00:00+08', '2026-10-28 17:00:00+08', NULL, NULL, 4, 'published', '2026-10-26 12:17:03.374+08', '2026-10-26 12:17:03.374+08', NULL);
