INSERT INTO public.event (id, organizer_id, org_name, category, title, body, campus, venue, starts_at, ends_at, capacity, team_size, signup_count, status, created_at, updated_at, deleted_at) VALUES ('b6b0a44a-2eaa-4c8a-aa58-5e1c4b931dfc', 'c43d6df5-b777-49d0-9622-d609aec7caee', 'ZJU Language Exchange', 'talk', 'Language corner — Chinese, English, everything else', 'Forty-five minutes in one language, then everyone switches. Beginners especially welcome; nobody is here to judge your tones.', 'yuquan', 'Library café, Yuquan', '2026-10-29 19:00:00+08', '2026-10-29 21:00:00+08', 60, NULL, 3, 'published', '2026-10-26 12:17:03.376+08', '2026-10-26 12:17:03.376+08', NULL);
