INSERT INTO public.event (id, organizer_id, org_name, category, title, body, campus, venue, starts_at, ends_at, capacity, team_size, signup_count, status, created_at, updated_at, deleted_at) VALUES ('aad3c7ea-76fd-45eb-b810-06c5c52e828f', 'c43d6df5-b777-49d0-9622-d609aec7caee', 'ZJU International Student Union', 'culture', 'Film night — Chinese cinema with subtitles', 'A different film each month, always with English subtitles, always followed by an argument about it in the corridor.', 'zijingang', 'Lecture hall 2, Zijingang', '2026-10-21 19:00:00+08', '2026-10-21 22:00:00+08', 80, NULL, 2, 'published', '2026-10-26 12:17:03.378+08', '2026-10-26 12:17:03.378+08', NULL);
INSERT INTO public.event (id, organizer_id, org_name, category, title, body, campus, venue, starts_at, ends_at, capacity, team_size, signup_count, status, created_at, updated_at, deleted_at) VALUES ('4722e20c-2f4f-4d26-ab79-38bbc425c139', '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', 'ZJU Photography Society', 'club', 'Campus photo walk — golden hour at Zijingang', 'Ninety minutes around the lake and the old library, with a short tip for each stop. Any camera is fine, a phone included.
INSERT INTO public.event (id, organizer_id, org_name, category, title, body, campus, venue, starts_at, ends_at, capacity, team_size, signup_count, status, created_at, updated_at, deleted_at) VALUES ('d6d601a7-7599-439c-abbe-38260b3a79f5', '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', 'ZJU Badminton Club', 'sports', 'Doubles evening — all levels, pairs sign up together', 'Round-robin doubles, short games so everyone plays a lot. Rackets can be borrowed at the desk.
INSERT INTO public.event (id, organizer_id, org_name, category, title, body, campus, venue, starts_at, ends_at, capacity, team_size, signup_count, status, created_at, updated_at, deleted_at) VALUES ('51d3afff-5277-4707-bd04-68273f7f6871', 'c43d6df5-b777-49d0-9622-d609aec7caee', 'ZJU Music Society', 'culture', 'Open mic night — bring a song, or just listen', 'Three minutes each, any language, any instrument. The piano is tuned this time.
INSERT INTO public.event (id, organizer_id, org_name, category, title, body, campus, venue, starts_at, ends_at, capacity, team_size, signup_count, status, created_at, updated_at, deleted_at) VALUES ('3475e7b8-f119-49e6-8776-57317f271008', 'c43d6df5-b777-49d0-9622-d609aec7caee', 'ZJU Board Game Society', 'club', 'Board game café night — learn something new', 'Two tables of easy games for first-timers and two for people who already own too many. Snacks on the house.', 'yuquan', 'Club room 3, Yuquan', '2026-11-05 19:00:00+08', '2026-11-05 22:00:00+08', 10, NULL, 9, 'published', '2026-10-26 12:17:03.382+08', '2026-10-26 12:17:03.382+08', NULL);
INSERT INTO public.event (id, organizer_id, org_name, category, title, body, campus, venue, starts_at, ends_at, capacity, team_size, signup_count, status, created_at, updated_at, deleted_at) VALUES ('c7d271db-9dad-459e-8ea0-c26222edab2a', 'c43d6df5-b777-49d0-9622-d609aec7caee', 'ZJU Debate Club', 'talk', 'Beginner debate workshop — no experience needed', 'We give you a motion, ten minutes to prepare, and a friendly room. The point is to find out that you can do this, not to win.
INSERT INTO public.event (id, organizer_id, org_name, category, title, body, campus, venue, starts_at, ends_at, capacity, team_size, signup_count, status, created_at, updated_at, deleted_at) VALUES ('a72b5c50-2cf4-4e9d-a114-73fd1d6da356', '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', 'ZJU Volunteer Association', 'club', 'Weekend volunteering — English corner at a community school', 'Half a day with primary school children who want to practise their English. No teaching experience needed; we send a short plan beforehand.
INSERT INTO public.event (id, organizer_id, org_name, category, title, body, campus, venue, starts_at, ends_at, capacity, team_size, signup_count, status, created_at, updated_at, deleted_at) VALUES ('cace18cf-7c99-4456-b194-cc95a6796414', 'c43d6df5-b777-49d0-9622-d609aec7caee', 'ZJU International Student Union', 'party', 'International food market — twelve countries, one square', 'Stalls run by student groups: bring cash or WeChat Pay, and an appetite. Each stall has an ingredients card for anyone with allergies.', 'zijingang', 'Main square, Zijingang', '2026-11-15 17:00:00+08', '2026-11-15 21:00:00+08', NULL, NULL, 3, 'published', '2026-10-26 12:17:03.385+08', '2026-10-26 12:17:03.385+08', NULL);
INSERT INTO public.event (id, organizer_id, org_name, category, title, body, campus, venue, starts_at, ends_at, capacity, team_size, signup_count, status, created_at, updated_at, deleted_at) VALUES ('d619cd8e-a293-466f-8d87-c5a6127c537c', '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', 'Hangzhou Walks', 'culture', 'West Lake sunrise walk', 'Up early for the quietest hour at the lake. Easy flat walking, about two hours, with breakfast at the end.
INSERT INTO public.event (id, organizer_id, org_name, category, title, body, campus, venue, starts_at, ends_at, capacity, team_size, signup_count, status, created_at, updated_at, deleted_at) VALUES ('88e2d97a-51c5-4f3b-a2bc-1b6e9acd4f49', 'c43d6df5-b777-49d0-9622-d609aec7caee', 'ZJU Career Centre', 'talk', 'Working in China after graduation — a panel for international students', 'Three alumni talk about finding a first job, what employers ask, and what they wish they had known. Questions from the room at the end.
