INSERT INTO public.listing (id, user_id, category_id, title, description, price_type, price_cents, condition, campus, meetup_note, status, published_at, expires_at, bumped_at, view_count, created_at, updated_at, deleted_at, previous_price_cents, wechat_ok) VALUES ('d0aff33a-29e9-4b06-9407-63c3d756b4a8', '4e27e6d2-8567-43e2-a99d-58fdee7f7182', '414113d5-5e26-4d92-8153-dfa367203abf', 'Introduction to Machine Learning', 'Selling my whole course reading list before I graduate. Message me if you want several — happy to do a deal.', 'fixed', 45000, 'good', 'zijingang', NULL, 'active', '2026-10-10 10:49:18.279+08', '2026-11-09 16:49:18.279+08', '2026-10-10 10:49:18.279+08', 17, '2026-10-10 10:49:18.279+08', '2026-10-10 16:49:18.663784+08', NULL, NULL, true);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('186d89fd-50b0-4151-a6ba-cb61fa22d0b3', 3, '97024d98-d168-430c-b8f2-e676102d3cb5', 'question', 'Residence permit renewal — how early did you start?', 'Mine expires at the end of next month. The checklist I got in orientation is two years old and I am not sure it is still current.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('7a644704-8f08-415c-a487-d60335d430b5', 5, 'c43d6df5-b777-49d0-9622-d609aec7caee', 'tip', 'Best cheap lunch within 10 minutes of Zijingang?', 'Starting a thread so new students have one place to look. Under ¥30, walkable, go.', 'zijingang', NULL, 61, 5, '2026-10-25 16:17:03.202+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('2815ee4f-825d-4642-a3f2-b1ca2b9ac948', 2, '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'question', 'Moving off campus next semester — what should I check before signing?', 'First time renting in China. Landlord seems nice but the contract is only in Chinese. What do people usually check, and is there somewhere I can get the contract looked at?', 'haining', NULL, 27, 4, '2026-10-26 03:17:03.207+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('3e069cfc-20d9-4d8f-8b62-604e3cd82dd5', 4, 'bf0be4b1-c969-4b0d-a7de-4e7a368b5284', 'discussion', 'Study group for Linear Algebra final — anyone?', 'Thinking twice a week in the library, working through past problem sets together. English or Chinese both fine.', NULL, NULL, 38, 5, '2026-10-25 06:17:03.209+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('3fd9885b-4193-489a-a683-db6420ce41ef', 7, '65c43f4b-c3c3-463b-a86b-d682a8e5b553', 'discussion', '中英语言交换 · 找一位英语母语的语伴', '我是玉泉校区的研二学生，想练口语。可以帮你练中文（普通话），每周一到两次，校内咖啡店见面。
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('4a12965b-e6ff-4e02-89db-2d8d9abd8d3a', 1, '6c41022b-e840-4297-bd7d-77b9a9fa0b08', 'tip', 'Things I wish I knew in my first month at ZJU', '1. Get a local phone number early, a lot of apps need it.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('65340ff5-34f5-45de-840e-4f5c64082229', 15, 'bd45f4db-2af8-4b41-ab23-99182bad787c', 'event', 'Saturday badminton — 4 more players needed', 'We have two courts booked this Saturday afternoon at the Zijingang sports centre. All levels welcome, bring your own racket if you have one.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('dc35dfd1-9d8f-4042-b133-408a1318156c', 15, '97024d98-d168-430c-b8f2-e676102d3cb5', 'discussion', 'Ping pong before class — looking for a regular partner', 'The tables in the Yuquan gym building are usually free before 9am. I am somewhere between beginner and bad, so there is no level to live up to here.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('55c28244-ddd1-4920-b9d8-7bda73a521ac', 15, '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'event', 'Sunday football at Zijingang — mixed levels, always short a keeper', 'We play most Sundays at 4pm. Usually a mix of international and Chinese students, usually about twelve of us, almost always missing a goalkeeper.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('d4c33ff9-94e2-434e-9230-e87d42773a6e', 16, '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'question', 'Which clubs actually take international students?', 'Not which ones say they are open — which ones did you join and feel welcome in? My Chinese is still basic and I would rather hear it from someone who has done it.', NULL, NULL, 37, 4, '2026-10-24 20:17:03.219+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('798284ee-33ac-4d43-a7f2-57680c8cc8fb', 16, 'bf0be4b1-c969-4b0d-a7de-4e7a368b5284', 'event', 'Photography society open session on Thursday — no camera needed', 'Thursday evening is an open session, so you can come without joining anything. A phone is fine; half the people bring nothing at all and just walk with us.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('6702ed47-7af3-4cfb-aa1c-342ceb75ccc3', 16, '65c43f4b-c3c3-463b-a86b-d682a8e5b553', 'discussion', '街舞社招新，欢迎留学生同学', '每周三、周日晚上在玉泉体育馆排练，零基础也可以来，前两次是免费体验。
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('aebb75fb-400f-4d3f-968e-0307127ca7d3', 6, '4ce21260-7836-49a7-88cb-47902ce5a22b', 'event', 'International potluck next Friday — one dish from home each', 'Someone organised this last year and it was the best evening of the semester. One dish each, and write what is in it on a card beside it so people know what they are eating.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('da103e5c-eae2-4d00-8e26-dc69c3c7adcb', 8, '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'question', 'Part-time work or internships as an international student — what is allowed?', 'I have heard different things from different people. Some say internships are fine with approval, some say not at all. Has anyone actually gone through the process?', NULL, NULL, 29, 3, '2026-10-23 14:17:03.224+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('bd1f68ab-e662-4b11-8151-561620580def', 2, '4ce21260-7836-49a7-88cb-47902ce5a22b', 'tip', 'Setting up a dorm room on a budget', 'Most of what you need is already on the Marketplace from students who are moving out. I got a desk, lamp and bedding for under ¥300 total.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('ffc3412d-6474-4304-a57e-d957a01e1caa', 4, '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', 'question', '有没有同学选过「国际商法」？考试难吗？', '下学期想选这门课，想了解一下考核方式和课程压力。英文授课的班级有什么需要注意的吗？', 'zhijiang', NULL, 16, 2, '2026-10-24 08:17:03.226+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('d9c63746-c559-4225-abdd-86c248cd18e5', 5, '97024d98-d168-430c-b8f2-e676102d3cb5', 'discussion', 'West Lake on a weekday morning is a completely different place', 'Went at 7am on a Wednesday. Almost empty, mist on the water, locals doing tai chi. If you have only been on a weekend you have not really seen it.', NULL, NULL, 52, 3, '2026-10-22 12:17:03.227+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('83aa82d3-d057-4e48-894e-8bdaf515b027', 1, 'bf0be4b1-c969-4b0d-a7de-4e7a368b5284', 'question', 'Is there a quiet place to study late at night?', 'The main library closes before I am done most days. Where do people go?', 'zijingang', NULL, 11, 2, '2026-10-26 00:17:03.228+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('257d0ac9-b14e-4230-bf4e-96ac1af30552', 3, 'c43d6df5-b777-49d0-9622-d609aec7caee', 'tip', 'Opening a bank account — what made it easier for me', 'Took me two tries. What worked the second time: going on a weekday morning, bringing passport + residence permit + student card + a local phone number, and having a Chinese-speaking friend come along.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('4ae84a71-db21-4452-88ee-8bf89af79118', 6, '65c43f4b-c3c3-463b-a86b-d682a8e5b553', 'event', '周末去杭州植物园拍照，有人一起吗？', '周六上午出发，地铁过去，大概半天。欢迎带相机或者手机都行，主要是散步和拍照。
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('940c7869-ddc0-4471-b8ea-d6734eabf2d9', 4, '6c41022b-e840-4297-bd7d-77b9a9fa0b08', 'tip', 'Free tools that got me through my first semester of courses in Chinese', 'A pop-up dictionary browser extension for course websites, a flashcard app for the technical vocabulary of each course, and asking one Chinese classmate per course if I could compare notes after lectures.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('fcdd5f44-c7cd-487a-8da5-d6fddc6f1557', 7, '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'question', 'Looking for a Mandarin speaking partner — Arabic or English in return', 'HSK 4, want to get better at everyday conversation, not exam Chinese. Happy to teach Arabic or practise English.', 'zijingang', NULL, 13, 1, '2026-10-24 20:17:03.231+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('05da4174-6194-47ba-bc03-58f85159e15c', 8, 'bd45f4db-2af8-4b41-ab23-99182bad787c', 'discussion', 'CV format for Chinese companies vs European ones', 'Noticed Chinese job postings often expect a photo and more personal details on the CV, which is the opposite of what I was taught at home. How do people handle this?', NULL, NULL, 21, 2, '2026-10-18 04:17:03.231+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('8388b347-4c1b-490f-9413-c2d5a00e4664', 2, '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', 'question', '之江校区附近有推荐的短租吗？', '暑假有一个月需要留在杭州，宿舍不能住，想找一个短租的地方。', 'zhijiang', NULL, 8, 1, '2026-10-26 05:17:03.231+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('ef959e08-9251-41c4-815c-628f7564bffb', 1, '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'discussion', 'Haining campus appreciation post 🌿', 'Smaller than the Hangzhou campuses but honestly the most beautiful. The lake at sunset is unreal.', 'haining', NULL, 35, 3, '2026-10-23 04:17:03.232+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('1824b557-55f6-4bd5-8600-6895872c2f3e', 4, '97024d98-d168-430c-b8f2-e676102d3cb5', 'question', 'Where do people find past exam papers?', 'Some courses seem to have them floating around, some do not. Is there an official place?', NULL, NULL, 3, 0, '2026-10-26 10:17:03.233+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('94b07edd-a99e-49a7-8271-738a0ca2b736', 5, 'bf0be4b1-c969-4b0d-a7de-4e7a368b5284', 'tip', 'The little bakery behind the south gate is worth the detour', 'Opens early, sells out of the milk bread by nine. Around ¥6 for a loaf, and the owner does not mind if you point at things.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('94c1a364-fef4-417b-ac4a-fc4604e9d542', 4, 'bd45f4db-2af8-4b41-ab23-99182bad787c', 'question', 'How do you handle group projects when half the group is still learning the language?', 'We have a team of five from four countries and our meetings drift into three languages. We are not fighting, just slow.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('2b764320-15c6-4f96-a9a9-b26e20a73789', 3, '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'tip', 'Setting up mobile payments as a foreigner — what worked for me', 'This is my experience, not a rule, so check with your bank. I linked a Chinese bank card to Alipay first, then WeChat Pay a day later.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('9e3c7b09-e750-4000-b794-858349639630', 1, '4ce21260-7836-49a7-88cb-47902ce5a22b', 'question', 'Quiet places to study after the library closes?', 'The library is lovely but shuts earlier than I work. Anywhere at Yuquan with a table, a plug and not too much noise?', 'yuquan', NULL, 12, 2, '2026-10-26 01:17:03.235+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('5574a94b-4348-49ac-b63d-b031b940c639', 15, '97024d98-d168-430c-b8f2-e676102d3cb5', 'discussion', 'Anyone up for a running group around the lake?', 'Early mornings, easy pace, about 5 km. Nobody left behind: we wait at the corners.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('b515b08d-c4da-4f57-8160-a6bc625547c9', 2, '65c43f4b-c3c3-463b-a86b-d682a8e5b553', 'tip', '合租找室友的几点经验', '1. 先说清楚作息和卫生习惯，别等住进去再讨论。
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('66ab9845-93f7-47fc-833d-24ca7e35db85', 16, 'c43d6df5-b777-49d0-9622-d609aec7caee', 'event', 'Photography society is recruiting — no gear needed', 'We meet every second week for a walk and share what we shot. Phones are completely fine, and so is zero experience.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('84ca1117-3816-4f3e-8ad6-ff547bffa3e5', 7, '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'question', 'Good ways to practise characters beyond a dictionary app?', 'I can read menus on a good day but I forget everything I do not use. Flashcards help a little. What actually stuck for you?', NULL, NULL, 17, 3, '2026-10-24 20:17:03.239+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('58bcdbec-ca1b-4420-90f2-567158756adf', 8, '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', 'tip', 'Internship search: what worked for me as an international student', 'Not a guarantee, just what I did. I asked my department which companies had taken international students before, and I wrote to those first.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('f11b7f81-65bb-4322-9f50-d4219e0293d6', 6, '6c41022b-e840-4297-bd7d-77b9a9fa0b08', 'discussion', 'What dish are you bringing to the semester-end potluck?', 'Starting a thread so we do not end up with nine salads. I am thinking something simple that travels well.', 'zijingang', NULL, 24, 4, '2026-10-26 04:17:03.24+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('6f30cb64-ca4e-4d82-b0a8-ea8f01c86408', 1, 'bf0be4b1-c969-4b0d-a7de-4e7a368b5284', 'discussion', 'Small dorm tricks nobody told you about', 'Mine: a shower caddy that hangs from the door, a second power strip, and a bag of coins for the laundry.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('bda7167c-ea2b-431f-94c3-def5f6fd2d94', 5, 'bd45f4db-2af8-4b41-ab23-99182bad787c', 'question', 'Vegetarian food in Haining?', 'I have been eating a lot of plain rice. Is there somewhere that does proper vegetarian dishes, not just a bit of meat on the side?', 'haining', NULL, 6, 1, '2026-10-26 08:17:03.242+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('d2ffe7b8-8d10-42c1-8394-e30d4b262dc0', 15, '4ce21260-7836-49a7-88cb-47902ce5a22b', 'event', 'Looking for a fourth for badminton doubles tomorrow evening', 'Two of us and one more, intermediate level. We will be at the Zijingang courts around seven. DM me if you can make it.', 'zijingang', 'e1d9e69c-8897-4556-8968-f0d4fed4b262', 9, 2, '2026-10-25 16:17:03.242+08', NULL, NULL);
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('f7281b1b-58b0-40e7-9962-f76e5ea1fc9d', 6, 'c43d6df5-b777-49d0-9622-d609aec7caee', 'event', 'Autumn welcome party — everyone is invited, nothing to pay', 'Friday from seven at the Student Centre. Music, food from a dozen countries, and a room full of people who also arrived this year.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('e82f6a56-89da-4ea1-8254-dc4851e37c8a', 6, '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', 'event', 'Longjing hike: what to bring and where we meet', 'Comfortable shoes, water, and a layer for the top. We meet at the metro exit and walk about three hours, with a long tea stop halfway.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('a9598e8b-eda1-4ef6-be61-d37f9df7e211', 6, 'c43d6df5-b777-49d0-9622-d609aec7caee', 'event', 'Running a stall at the international food market? Read this first', 'Student groups can still take a table. Tell us what you are cooking, and put an ingredients card on the front for anyone with allergies.
INSERT INTO public.post (id, board_id, user_id, kind, title, body, campus, listing_id, score, comment_count, created_at, deleted_at, event_id) VALUES ('fe3d9af2-f6ac-4110-825d-ea84186cfecf', 6, 'c43d6df5-b777-49d0-9622-d609aec7caee', 'event', 'Potluck sign-up: what are you bringing?', 'Reply here with your dish so we can keep the table varied. Rice, plates and tea are on us. Vegetarian and halal dishes are especially welcome.', 'zijingang', NULL, 12, 0, '2026-10-24 08:17:03.396+08', NULL, '6bde1777-80e8-4c58-bb05-d599e77ca0a5');
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('adcf06b2-a105-49ae-b571-665769286b7c', '186d89fd-50b0-4151-a6ba-cb61fa22d0b3', NULL, '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'I started about six weeks before. The International Student Office sends an email with the current checklist each semester, so I would go by that rather than the old one.', 18, '2026-10-26 08:17:03.187+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('f13275d9-22d2-490f-9e58-80022ea49698', '186d89fd-50b0-4151-a6ba-cb61fa22d0b3', 'adcf06b2-a105-49ae-b571-665769286b7c', '97024d98-d168-430c-b8f2-e676102d3cb5', 'Found it in my university inbox, thanks. It had changed.', 6, '2026-10-26 09:17:03.199+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('d18326f2-a7cb-4356-ad96-dadb171434fc', '186d89fd-50b0-4151-a6ba-cb61fa22d0b3', NULL, 'bd45f4db-2af8-4b41-ab23-99182bad787c', 'Bring more passport photos than you think you need. I had to go back once.', 11, '2026-10-26 10:17:03.199+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('c1367dc2-7686-451b-8474-2808e06fed29', '186d89fd-50b0-4151-a6ba-cb61fa22d0b3', 'd18326f2-a7cb-4356-ad96-dadb171434fc', '6c41022b-e840-4297-bd7d-77b9a9fa0b08', 'Same. Also make copies of every passport page with a stamp.', 3, '2026-10-26 11:17:03.2+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('84ca26b5-968a-42de-b34b-b765515135c2', '186d89fd-50b0-4151-a6ba-cb61fa22d0b3', NULL, '4ce21260-7836-49a7-88cb-47902ce5a22b', 'Book the appointment as soon as the slots open, they fill up near the end of the semester.', 4, '2026-10-26 11:17:03.201+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('8e153ca0-f2ff-4702-9dc2-1500c07f7b01', '7a644704-8f08-415c-a487-d60335d430b5', NULL, '65c43f4b-c3c3-463b-a86b-d682a8e5b553', 'The noodle place by the north gate. Ask for less chilli if you are new to it, "shao la" works.', 22, '2026-10-25 17:17:03.205+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('7c97012c-afce-4268-a0d1-1b1ff58a305d', '7a644704-8f08-415c-a487-d60335d430b5', '8e153ca0-f2ff-4702-9dc2-1500c07f7b01', '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'Can confirm, and they have a picture menu.', 9, '2026-10-25 18:17:03.206+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('f0a1a6e6-b1fd-488f-a544-255643f144ad', '7a644704-8f08-415c-a487-d60335d430b5', '8e153ca0-f2ff-4702-9dc2-1500c07f7b01', 'bf0be4b1-c969-4b0d-a7de-4e7a368b5284', '少辣 is the magic word 😄', 5, '2026-10-25 19:17:03.206+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('2316ff5a-fc0c-445f-acce-54796564106f', '7a644704-8f08-415c-a487-d60335d430b5', NULL, '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'Canteen 2 upstairs does a decent set meal. Not exciting, very reliable.', 14, '2026-10-25 18:17:03.207+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('4cb457e3-8858-488b-b122-60b7ab1b1241', '7a644704-8f08-415c-a487-d60335d430b5', NULL, '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', '食堂的麻辣香锅性价比很高，中午人多建议早点去。', 7, '2026-10-25 21:17:03.207+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('154f169d-f0d8-4e36-8b5f-dd2dd9893ac5', '2815ee4f-825d-4642-a3f2-b1ca2b9ac948', NULL, '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', 'Ask whether the landlord will help with the accommodation registration — you usually need to register your address after moving. Confirm the exact steps with the International Student Office.', 15, '2026-10-26 04:17:03.208+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('1d6aba58-1f38-4a5b-a1eb-41b3b581aa38', '2815ee4f-825d-4642-a3f2-b1ca2b9ac948', '154f169d-f0d8-4e36-8b5f-dd2dd9893ac5', '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'Did not know about that at all, thank you.', 4, '2026-10-26 05:17:03.208+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('c58d2657-e7e9-4bf1-b60e-319064895899', '2815ee4f-825d-4642-a3f2-b1ca2b9ac948', NULL, 'c43d6df5-b777-49d0-9622-d609aec7caee', 'Photograph every room and every existing scratch before you move in, and send the photos to the landlord in WeChat so there is a timestamp.', 9, '2026-10-26 06:17:03.208+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('b1591ba4-c627-40de-8dfb-f0f5f614f787', '2815ee4f-825d-4642-a3f2-b1ca2b9ac948', NULL, 'bd45f4db-2af8-4b41-ab23-99182bad787c', 'Check who pays for water, electricity and internet, and how the deposit is returned. Get it written in the contract.', 3, '2026-10-26 09:17:03.209+08', NULL);
