INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('77e8b5a2-de95-41b7-b1f5-0fbff7d376f2', 'd4c33ff9-94e2-434e-9230-e87d42773a6e', NULL, '6bd7a02d-60f5-4844-9adf-41f9aa05d4ee', '其实大部分社团都欢迎留学生，只是很少有人主动来问。建议直接去活动现场看看，比在群里发消息有用得多。', 19, '2026-10-25 00:17:03.219+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('fe0dc689-e1f8-4739-a88c-da29fa3c2956', 'd4c33ff9-94e2-434e-9230-e87d42773a6e', '77e8b5a2-de95-41b7-b1f5-0fbff7d376f2', '34ac95c3-cd63-4251-8baf-d35b165b8ac1', 'That is encouraging, thank you. I think I was overthinking it.', 7, '2026-10-25 02:17:03.22+08', NULL);
INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('10fce18a-7f1b-4a08-a6b0-dfc09956ff9c', 'd4c33ff9-94e2-434e-9230-e87d42773a6e', NULL, '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'Photography, badminton and the volunteer societies all had someone who switched to English the moment I turned up. The academic ones were harder going.', 14, '2026-10-25 03:17:03.22+08', NULL);
