INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('8f116a7d-a237-4312-90bc-b5724924de62', 'da103e5c-eae2-4d00-8e26-dc69c3c7adcb', 'd87afd5f-4ac0-4d43-9bb3-830bbcf93573', '4e27e6d2-8567-43e2-a99d-58fdee7f7182', 'Fair. I will book a meeting with them.', 7, '2026-10-23 20:17:03.225+08', NULL);
