INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('d00b8dca-9c53-499b-abf5-5e725a477504', 'bd1f68ab-e662-4b11-8151-561620580def', NULL, 'c43d6df5-b777-49d0-9622-d609aec7caee', 'Also: a small power strip with a switch. Plugs are never where you want them.', 6, '2026-10-25 15:17:03.226+08', NULL);
