INSERT INTO public.comment (id, post_id, parent_id, user_id, body, score, created_at, deleted_at) VALUES ('ce33963f-352f-46c5-ac8e-68416861302c', '94c1a364-fef4-417b-ac4a-fc4604e9d542', NULL, 'c43d6df5-b777-49d0-9622-d609aec7caee', 'Write the plan down in simple English before the meeting, and use the meeting only to agree or disagree with it. Much faster than talking it out.', 12, '2026-10-25 23:17:03.234+08', NULL);
